if ( ! $this->is_global() ) {
	// Site creation switches blogs before WordPress creates its options table.
	if ( doing_action( 'wp_initialize_site' ) && ! wp_is_site_initialized( $site_id ) ) {
		$this->db_version = false;
	} else {
		$this->db_version = get_blog_option( $site_id, $this->db_version_key, false );
	}
}
